on conflict(metric_code) do update set label=excluded.label,dimension=excluded.dimension,unit_kind=excluded.unit_kind,default_unit=excluded.default_unit,default_currency=excluded.default_currency,comparable_scope=excluded.comparable_scope,higher_means_more_weight=excluded.higher_means_more_weight,description=excluded.description,sort_order=excluded.sort_order;

with vals(fintech_id,primary_vertical,business_model,target_customer,revenue_model,bm_conf,tc_conf,rev_conf,bm_basis,tc_basis,rev_basis,source_url) as (
 values
 ('ENT-RUT-77066914-6','Procesamiento de pagos y remesas','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'ProntoPaga es una infraestructura regional de PayIns, PayOuts y pagos a terceros integrada mediante API para comercios y empresas.','La oferta vigente se dirige a negocios, e-commerce, servicios financieros y otras empresas que integran recaudación y dispersión de pagos.','La documentación pública describe la infraestructura y operación, pero no publica una tarifa principal suficientemente generalizable para asignar un único modelo de ingresos.','https://www2.prontopaga.com/home-chile-es/'),
 ('ENT-RUT-77645606-3','WealthTech / Asesoría de inversión','B2B','EMPRESAS','ASESORIA_HONORARIOS',0.999::numeric,0.999::numeric,0.99::numeric,'Farellones Capital es una boutique de inversión y asesor de inversión RPSF que actúa como portfolio/investment manager bajo mandato delegado.','Sus servicios están restringidos a inversionistas calificados, institucionales y family offices calificados.','La actividad observable consiste en asesoría/gestión bajo mandato para inversionistas y vehículos; se representa como honorarios de asesoría/gestión dentro de la taxonomía disponible.','https://www.farcap.cl/'),
 ('ENT-RUT-77227254-5','WealthTech / Asesoría de inversión','B2B2C','AMBOS',null,0.999::numeric,0.999::numeric,null,'Ursa desarrolla sistemas de inversión cuantitativa y ofrece asesoría de inversión y gestión patrimonial mediante estrategias multiactivo.','La oferta admite clientes/inversionistas y contempla expresamente la posibilidad de invertir como persona jurídica.','El sitio no publica una tarifa suficientemente explícita para representar una única monetización principal.','https://ursagroup.cl/'),
 ('ENT-RUT-77121015-5','Mercados / FX institucional','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'MesaDinero ofrece liquidez FX, cobertura, derivados, pagos transfronterizos y conectividad a mercados para empresas, instituciones financieras y family offices.','El sitio identifica explícitamente como clientes a corporativos, instituciones financieras y family offices.','La plataforma declara spreads institucionales sin márgenes ocultos y actúa como canal/referenciamiento hacia terceros; no se fuerza un modelo de ingresos único.','https://www.mesadinero.com/')
), logged as (
 select v.fintech_id,'MANUAL_OFFICIAL_REGULATED_ECONOMIC_VERTICAL_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,v.revenue_model,v.rev_conf,1,now(),jsonb_build_object('source_url',v.source_url,'economic_vertical',v.primary_vertical,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'manual_validation',true,'cohort','REGULATED_ECONOMIC_VERTICALS') from vals v returning fintech_id
)
update public.aml_fintech_entity e
set primary_vertical=v.primary_vertical,business_model=v.business_model,target_customer=v.target_customer,revenue_model=v.revenue_model,business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=v.rev_basis,revenue_model_confidence=v.rev_conf,profile_classifier_version='MANUAL_OFFICIAL_REGULATED_ECONOMIC_VERTICAL_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
from vals v where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

on conflict(observation_key) do update set evidence_status=excluded.evidence_status,evidence_class=excluded.evidence_class,confidence=excluded.confidence,basis=excluded.basis,source_code=excluded.source_code,source_url=excluded.source_url,evidence_excerpt=excluded.evidence_excerpt,last_seen_at=now(),observed_at=excluded.observed_at;

on conflict(observation_key) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,qualifier=excluded.qualifier,evidence_type=excluded.evidence_type,confidence=excluded.confidence,source_url=excluded.source_url,observed_at=excluded.observed_at,basis=excluded.basis,evidence_excerpt=excluded.evidence_excerpt,metadata=excluded.metadata,last_seen_at=now();

select public.aml_fintech_refresh_functional_profile();